values ('legal_content', $j${"title": "الخصوصية والاستخدام", "subtitle": "سياسة الخصوصية وشروط الاستخدام", "updated": "2026-10-27", "sections": [{"key": "privacy", "title": "بياناتك وخصوصيتك", "items": [{"id": "collect", "title": "ما نجمعه", "lines": ["رقم هاتفك لتسجيل الدخول فقط.", "اسمك وقرابتك وتاريخ الميلاد أو الوفاة لبناء الشجرة.", "وما تختار إضافته بنفسك: صورتك، نبذتك، ديوانيتك، مشروعك."]}, {"id": "why", "title": "لماذا نجمعه", "lines": ["لتعرف العائلة بعضها، ولتعمل الشجرة والأخبار والإشعارات.", "لا إعلانات، ولا بيع لبياناتك، ولا مشاركتها لأي غرض تجاري."]}, {"id": "who", "title": "من يرى بياناتك", "lines": ["أعضاء العائلة المعتمدون فقط داخل التطبيق.", "ويمكنك إخفاء رقمك وبعض معلوماتك من الإعدادات."]}, {"id": "otp", "title": "رمز الدخول", "lines": ["يصلك برسالة نصية (SMS) لمرة واحدة، ولا نرسل عبرها أي محتوى آخر."]}, {"id": "providers", "title": "الخدمات التي نعتمد عليها", "lines": ["Supabase لحفظ البيانات والصور، وإشعارات Apple وGoogle، وKWT SMS لرسائل الدخول.", "كلها تستخدم البيانات بقدر تشغيل الخدمة فقط."]}, {"id": "security", "title": "الحماية", "lines": ["اتصال مشفّر، وصلاحيات محددة لكل دور في الإدارة، وحدّ لعدد الأجهزة وحماية من تكرار طلب الرمز."]}, {"id": "delete", "title": "حذف حسابك", "lines": ["من الإعدادات في أي وقت؛ نحذف بياناتك الشخصية خلال ٣٠ يوماً.", "ويبقى اسمك في الشجرة فقط إذا كان ضرورياً لربط العائلة."]}]}, {"key": "terms", "title": "قواعد الاستخدام", "items": [{"id": "eligibility", "title": "لمن التطبيق؟", "lines": ["لأبناء عائلة المحمدعلي ومن توافق عليه الإدارة؛ كل تسجيل يُراجَع قبل التفعيل."]}, {"id": "account", "title": "حسابك مسؤوليتك", "lines": ["لا تشارك رمز الدخول مع أحد، وأبلغنا إن لاحظت دخولاً غريباً."]}, {"id": "respect", "title": "الاحترام أولاً", "lines": ["لا محتوى مسيء، ولا انتحال لشخصية أحد، ولا جمع لبيانات الأعضاء خارج التطبيق."]}, {"id": "content", "title": "ما تضيفه", "lines": ["يبقى ملكك ويظهر للعائلة داخل التطبيق.", "وللإدارة أن تراجعه أو تخفيه إذا خالف هذه القواعد."]}, {"id": "accuracy", "title": "دقة الشجرة", "lines": ["